select x.id, v.ci, v.ex, v.dn::jsonb, v.ac::jsonb
from (values
(1, 3, 'القانون العلمي يصف علاقة في الطبيعة تدعمها أدلة وتجارب كثيرة، مثل قانون حفظ الكتلة.', '["البحث النظري نوع من البحث لاكتساب المعرفة، وليس وصفًا لعلاقة في الطبيعة.","البحث التطبيقي بحث لحل مشكلة محددة.","النظرية تفسير لظاهرة مدعوم بالتجارب، أما وصف العلاقة نفسها فهو القانون.",""]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.416Z"}'::jsonb),
(2, 0, 'بعد ملاحظة الظاهرة يصوغ العالم فرضية، أي تفسيرًا مبدئيًا قابلًا للاختبار.', '["","الاستنتاج يأتي في آخر الطريقة بعد التجربة وتحليل البيانات.","تحليل النتائج يأتي بعد إجراء التجربة.","اختبار الفرضية بالتجربة يأتي بعد صياغتها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.416Z"}'::jsonb),
(3, 0, 'الفرضية تُختبر بالتجريب؛ فالتجربة هي التي تؤيد الفرضية أو تنفيها.', '["","الملاحظة تسبق صياغة الفرضية، ولا تثبتها.","التحليل يتم على بيانات التجربة، فلا يغني عنها.","الاستنتاج يُبنى على نتائج التجربة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.416Z"}'::jsonb),
(4, 2, 'هذه الجملة قانون حفظ الكتلة: علاقة ثابتة في الطبيعة دعمتها تجارب كثيرة.', '["النظرية تفسر سبب الظاهرة، والجملة تصف ما يحدث لا سببه.","الفرضية تفسير مبدئي لم يُختبر بعد، أما هذه فعلاقة ثابتة بالتجارب.","","الملاحظة مشاهدة واحدة، وهذه قاعدة عامة مثبتة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.416Z"}'::jsonb),
(5, 0, 'درجة الحرارة هي العامل الذي يغيّره المجرب، فهي العامل المستقل. وسرعة الذوبان هي العامل التابع.', '["","العامل التابع هو سرعة الذوبان التي تتغير تبعًا لدرجة الحرارة.","التجربة هي الإجراء كله، لا أحد عوامله.","العامل الضابط يُثبَّت للمقارنة، ودرجة الحرارة هنا متغيرة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.416Z"}'::jsonb),
(6, 1, 'المجرب يغيّر درجة الحرارة بنفسه، فهي العامل المستقل. وذوبان الملح هو العامل التابع.', '["العامل التابع هو مقدار الذوبان الذي يُقاس.","","العامل الضابط يبقى ثابتًا، ودرجة الحرارة هنا تتغير.","درجة الحرارة تتغير في التجربة، فلا تكون ثابتة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.416Z"}'::jsonb),
