from (values
(1, 'مادة تزيد من سرعة التفاعل دون أن تستهلك فيه:', null, 2025, '["المحفز","المثبط","المعقد المنشط","طاقة التنشيط"]'::jsonb, 'تذكر', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س15'),
(2, 'تضاف المواد الحافظة في صناعة الأغذية لكي:', null, 2024, '["تقلل طاقة التنشيط أثناء التفاعل","تساعد على عملية أكسدة الغذاء","تزيد قيمة الطاقة الناتجة من احتراق الغذاء","تعمل كمثبط للتفاعل"]'::jsonb, 'فهم', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س16'),
(3, 'وُضعت مادة غذائية في أربعة أنابيب، وسُكب في كل أنبوب إنزيم هاضم بكمية مختلفة، وسُجل مقدار طاقة التنشيط: الأنبوب 1: 25، والأنبوب 2: 22، والأنبوب 3: 23، والأنبوب 4: 26. أي الأنابيب كان الأسرع في التفاعل؟', null, 2025, '["1","2","3","4"]'::jsonb, 'تحليل', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س17'),
(4, 'قطعة خشب كتلتها 1 kg ونشارة خشب كتلتها 1 kg، قمنا بإشعال نشارة الخشب وقطعة الخشب معًا، فاحترقت النشارة أسرع من القطعة، ما المختلف بين النشارة والقطعة؟', null, 2025, '["التركيز","نوع المادة","الحرارة","مساحة السطح"]'::jsonb, 'فهم', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س18'),
(5, 'في الشكل، أي الإنزيمات التالية يعد أكثر فعالية؟', '[{"src":"qimg/tahsili/chem-u18-enzymes.svg","alt":"أربعة منحنيات طاقة للتفاعل نفسه، قمة 1 أعلاها ثم 2 ثم 3 ثم 4 أقلها"}]'::jsonb, 2021, '["1","2","3","4"]'::jsonb, 'تحليل', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س19'),
(6, 'ما العامل المؤثر عند تعريض التفاعل 1 و2 والمكون من المواد نفسها لظرفين مختلفين؟', '[{"src":"qimg/tahsili/chem-u18-catalyst.svg","alt":"منحنيا طاقة لتفاعل طارد من المواد نفسها: 2 قمته أعلى، و1 قمته أقل"}]'::jsonb, 2025, '["طبيعة المواد المتفاعلة","تركيز المواد المتفاعلة","درجة الحرارة","العامل المحفز"]'::jsonb, 'تحليل', null, 'متوسط', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س20'),
(7, 'لماذا يذوب 50 g من مسحوق السكر أسرع من 50 g سكر متماسك؟', null, 2024, '["بسبب مساحة السطح","درجة الحرارة","الضغط","المواد المحفزة"]'::jsonb, 'فهم', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س21'),
(8, 'تصدأ برادة الحديد بشكل أسرع من قضيب الحديد عندما تتفاعل مع الأكسجين لأنه يعتمد على:', null, 2022, '["مساحة السطح","درجة الحرارة","الضغط","المواد المحفزة"]'::jsonb, 'فهم', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س22'),
(9, 'ترتبط جزيئات المادة المتفاعلة بموقع خاص على سطح إنزيم فتتفاعل، ثم تنفصل النواتج ويعود الإنزيم كما كان. ما وظيفة هذا الإنزيم؟', null, 2024, '["يستهلك في التفاعل","يقلل طاقة التنشيط","يزيد النواتج","يزيد المتفاعلات"]'::jsonb, 'فهم', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س23'),
(10, 'عالم كان يجري تجربة على خلية إنسان ولكن تفاعلها بطيء، فماذا يفعل ليكون التفاعل أسرع؟', null, 2024, '["إضافة إنزيم","زيادة طاقة التنشيط","رفع درجة الحرارة إلى 50 °C","إضافة مثبط"]'::jsonb, 'تطبيق', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س24'),
