(13, 'أي العوامل التالية لا يؤثر في سرعة التفاعل:', null, 2020, '["طبيعة المواد المتفاعلة","طبيعة المواد الناتجة","درجة الحرارة","التركيز"]'::jsonb, 'فهم', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س40'),
(14, 'سرعة التفاعل تتناسب ......... تركيز المتفاعلات', null, null, '["طرديًا مع","عكسيًا مع","طرديًا مع مربع","عكسيًا مع مربع"]'::jsonb, 'فهم', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س41'),
(15, 'الخارصين أسرع من النحاس عند التفاعل مع نترات الفضة بسبب', null, null, '["طبيعة المتفاعلات","درجة الحرارة","التركيز","مساحة السطح"]'::jsonb, 'فهم', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س42'),
(16, 'يبين رسم بياني أن سرعة التفاعل النسبية تزداد مع درجة الحرارة: 2 عند 290 K، و8 عند 310 K، و16 عند 320 K، و32 عند 330 K. كلما زادت درجة حرارة التفاعل زاد', null, 2020, '["حجم التفاعل","المادة المحفزة للتفاعل","ضغط التفاعل","عدد التصادمات بين الجسيمات"]'::jsonb, 'فهم', null, 'سهل', 'تجميعات يلو للكيمياء 2026 · سرعة التفاعلات الكيميائية · س43'),
