(10, 1, 'تكوّن مركب جديد (كربونات النحاس) يعني تفاعلًا كيميائيًا، فهي خاصية كيميائية.', '["تكونت مادة جديدة، فليست خاصية فيزيائية.","","الخاصية الكمية تُقاس بالأرقام، وهذا وصف لتفاعل.","ليست من تصنيفات خواص المادة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.439Z"}'::jsonb),
(11, 1, 'ذوبان الجليد تحوّل من الصلب إلى السائل دون تكوين مادة جديدة، فهو فيزيائي.', '["الحموضة تتعلق بتفاعل المادة، فهي خاصية كيميائية.","","الاتحاد بمادة أخرى تفاعل كيميائي.","عدم الاتحاد يصف قابلية التفاعل، فهو خاصية كيميائية أيضًا."]'::jsonb, '{"passed":false,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":false,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.439Z"}'::jsonb),
(12, 0, 'تغير لون الفضة (اسودادها) ناتج عن تفاعلها مع مركبات الكبريت وتكوين كبريتيد الفضة، فهو كيميائي.', '["","الغليان تغير في الحالة فقط.","التسامي تحول من صلب إلى غاز دون مادة جديدة.","ذوبان الجليد تغير في الحالة فقط."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.439Z"}'::jsonb),
(13, 0, 'التغير الفيزيائي يغيّر بعض الخواص الفيزيائية (كالشكل والحالة) دون تكوين مواد جديدة.', '["","الخاصية صفة للمادة، والسؤال عن تغير.","التغير الكيميائي ينتج عنه مادة جديدة.","الخاصية الكيميائية صفة لا تغير، وتظهر عند تكوين مواد جديدة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.439Z"}'::jsonb),
