(20, 2, 'التبلور: تُبخَّر كمية من المذيب أو يُبرَّد المحلول، فتنفصل بلورات المادة النقية.', '["التسامي لمادة تتحول من صلب إلى غاز مباشرة.","الكروماتوجرافيا لفصل مكونات مخلوط بحسب حركتها، لا للحصول على بلورات.","","الترشيح لا يفصل المادة الذائبة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T06:07:45.439Z"}'::jsonb),
